import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";
import { VFXFactory } from "../../graphics/VFXFactory"; 
import { THEME_IMPERIAL, THEME_COVENANT } from "../../../constants";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

// --- 1. FACTION ULTIMATES ---

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100; 
    p.type = 'PILLAR'; 
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; 
    p.type = 'DOMAIN'; 
    p.delay = 0;
    system.state.particles.push(p);

    // Add rising debris
    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; 
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; 
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// --- 2. SUPER ULTIMATES (Cinematic Levels) ---

// ☢️ TACTICAL NUKE (Mushroom Cloud)
export function spawnTacticalNuke(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Initial Blinding Flash
    const flash = system.state.getParticle();
    flash.x = x; flash.y = y; flash.z = 50;
    flash.life = 0.2; flash.maxLife = 0.2;
    flash.color = '#fff'; flash.size = 800; // Screen filler
    flash.type = 'GLOW'; // Reuse GLOW for simple flash
    system.state.particles.push(flash);

    // 2. The Stem (Rising Pillar of Fire/Smoke)
    const stemLayers = 8;
    for(let i=0; i<stemLayers; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 10;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 100 + i * 80; // Fast rising
        p.life = 1.5 + Math.random(); p.maxLife = p.life;
        p.color = i < 3 ? '#fbbf24' : '#4b5563'; // Fire bottom, Smoke top
        p.size = 40 + i * 5;
        p.type = 'SMOKE';
        p.delay = 0.1;
        system.state.particles.push(p);
    }

    // 3. The Cap (Expanding Mushroom Top)
    const capCount = 12;
    for(let i=0; i<capCount; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * 30;
        p.x = x + Math.cos(angle)*dist; 
        p.y = y + Math.sin(angle)*dist; 
        p.z = 250; // Start high
        p.vx = Math.cos(angle) * 80; // Expand outward
        p.vy = Math.sin(angle) * 80;
        p.vz = 20 + Math.random() * 40; // Slowly rise
        p.life = 2.0; p.maxLife = 2.0;
        p.color = Math.random() > 0.5 ? '#ef4444' : '#1f2937'; // Red/Dark Grey
        p.size = 60 + Math.random() * 40;
        p.type = 'SMOKE';
        p.rotation = Math.random() * Math.PI;
        p.delay = 0.3; // Wait for stem
        system.state.particles.push(p);
    }

    // 4. Ground Shockwave Rings
    for(let i=0; i<3; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 5;
        p.life = 0.8 + i * 0.2; p.maxLife = p.life;
        p.color = color;
        p.size = 150 + i * 50; 
        p.type = 'SHOCKWAVE';
        p.delay = i * 0.1;
        system.state.particles.push(p);
    }

    // 5. Debris flying everywhere
    spawnExplosion(system, x, y, 10, 20, '#000', 3.0, 1.5, 'DEBRIS');
}

// ☄️ METEOR IMPACT
export function spawnMeteorImpact(system: VFXSystem, x: number, y: number, color: string) {
    // 1. The Falling Rock (Fast Beam down)
    const meteor = system.state.getParticle();
    meteor.x = x - 200; meteor.y = y - 400; meteor.z = 0; // Visual start
    meteor.targetX = x; meteor.targetY = y;
    meteor.life = 0.2; meteor.maxLife = 0.2;
    meteor.color = '#ea580c'; meteor.size = 40;
    meteor.type = 'BEAM'; 
    system.state.particles.push(meteor);

    // 2. Massive Impact (Delayed)
    const delay = 0.2;

    // Core Blast
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 20;
    blast.life = 0.8; blast.maxLife = 0.8;
    blast.color = '#f97316'; blast.size = 120;
    blast.type = 'BLAST';
    blast.delay = delay;
    system.state.particles.push(blast);

    // Ejected Magma
    for(let i=0; i<15; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const spd = 100 + Math.random() * 300;
        p.x = x; p.y = y; p.z = 10;
        p.vx = Math.cos(angle) * spd;
        p.vy = Math.sin(angle) * spd;
        p.vz = 200 + Math.random() * 400;
        p.life = 1.0; p.maxLife = 1.0;
        p.color = Math.random() > 0.5 ? '#fca5a5' : '#7f1d1d';
        p.size = 6 + Math.random() * 8;
        p.type = 'SHARD';
        p.delay = delay;
        system.state.particles.push(p);
    }
}

// 🕳️ BLACK HOLE COLLAPSE
export function spawnBlackHoleCollapse(system: VFXSystem, x: number, y: number, color: string) {
    // 1. Event Horizon (Dark Sphere)
    const hole = system.state.getParticle();
    hole.x = x; hole.y = y; hole.z = 50;
    hole.vx = 0; hole.vy = 0; hole.vz = 0;
    hole.life = 1.5; hole.maxLife = 1.5;
    hole.color = '#000000'; hole.size = 100;
    hole.type = 'GLOW'; // Re-purposed as dark matter orb
    system.state.particles.push(hole);

    // 2. Accretion Disk (Swirling Particles INWARD)
    const count = 30;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        const dist = 200 + Math.random() * 100;
        p.x = x + Math.cos(angle) * dist;
        p.y = y + Math.sin(angle) * dist;
        p.z = 50;
        p.targetX = x; p.targetY = y; // Custom logic needed or simulate via velocity
        // Calculate velocity towards center
        const dx = x - p.x; const dy = y - p.y;
        const len = Math.sqrt(dx*dx + dy*dy);
        const speed = 400;
        p.vx = (dx/len) * speed;
        p.vy = (dy/len) * speed;
        p.vz = 0;
        p.life = len / speed; p.maxLife = p.life;
        p.color = Math.random() > 0.5 ? '#60a5fa' : '#c084fc';
        p.size = 4 + Math.random() * 4;
        p.type = 'SPARK'; // Streaks
        system.state.particles.push(p);
    }

    // 3. Final Pop (Delayed)
    const shock = system.state.getParticle();
    shock.x = x; shock.y = y; shock.z = 50;
    shock.life = 0.5; shock.maxLife = 0.5;
    shock.color = '#fff'; shock.size = 200;
    shock.type = 'RING';
    shock.delay = 1.2; // When collapse finishes
    system.state.particles.push(shock);
}

// --- 3. IMPACTS & EXPLOSIONS ---

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.life = 1.2; p.maxLife = 1.2;
    p.color = color;
    p.size = 36; 
    p.type = 'GRID_FIELD'; 
    p.delay = delay;
    system.state.particles.push(p);

    if (Math.random() > 0.5) {
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150; 
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; 
        p.life = duration + Math.random(); p.maxLife = p.life;
        p.color = color;
        p.size = 25 + Math.random() * 25; // Larger puffs
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;
        system.state.particles.push(p);
    }
}

export function spawnCastBreak(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    // Blast
    const blast = system.state.getParticle();
    blast.x = x; blast.y = y; blast.z = 20;
    blast.vx = 0; blast.vy = 0; blast.vz = 0;
    blast.life = 0.2; blast.maxLife = 0.2;
    blast.color = '#00ffff'; 
    blast.size = 100;
    blast.type = 'BLAST';
    system.state.particles.push(blast);

    // High Velocity Shards (Energy, not stone)
    const shardCount = 12;
    for(let i=0; i<shardCount; i++) {
        const p = system.state.getParticle();
        const angle = (Math.PI * 2 * i) / shardCount;
        const speed = 400 + Math.random() * 400; 
        p.x = x; p.y = y; p.z = 30;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 200 + Math.random() * 300; 
        p.life = 0.5 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = Math.random() > 0.5 ? color : '#e2e8f0'; 
        p.size = 5 + Math.random() * 5;
        p.type = 'SHARD';
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random() - 0.5) * 30; 
        system.state.particles.push(p);
    }

    // Chips
    const glitchCount = 8;
    for(let i=0; i<glitchCount; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*40;
        p.y = y + (Math.random()-0.5)*40;
        p.z = 40;
        p.vx = (Math.random()-0.5) * 50; 
        p.vy = (Math.random()-0.5) * 50;
        p.vz = 0;
        p.life = 0.3; p.maxLife = 0.3;
        p.color = Math.random() > 0.5 ? '#00ffff' : '#ff00ff';
        p.size = 4 + Math.random() * 4;
        p.type = 'CHIP'; 
        system.state.particles.push(p);
    }
}

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = 10;
    const spread = 0.8; 

    // Directional Cone Sparks (High speed light streaks)
    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 400 + Math.random() * 400; // Faster sparks
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.3 + Math.random() * 0.3; p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 4 + Math.random() * 6; // Larger kinetic sparks
        p.type = 'SPARK'; 
        p.delay = 0;
        system.state.particles.push(p);
    }

    if (isPhysical) {
        spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
    } else {
        // Magical impact ring
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = 0; p.vy = 0; p.vz = 0;
        p.life = 0.4; p.maxLife = 0.4;
        p.color = color;
        p.size = 20; 
        p.type = 'RING';
        system.state.particles.push(p);
    }
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

// 💥 IMPROVED UNIT SHATTER 💥
export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const isBlue = team === Team.BLUE;

    const theme = isBlue ? THEME_IMPERIAL : THEME_COVENANT;
    const baseColor = isBlue ? '#94a3b8' : '#27272a'; // Base debris (Pedestal)
    const armorColor = theme.primary; // Armor chunks
    const glowColor = isBlue ? THEME_IMPERIAL.energy : theme.secondary; // Soul energy

    // 1. Icon Sprite (Spinning out)
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 60; 
    const angle = Math.random() * Math.PI * 2;
    p.vx = Math.cos(angle) * 150; 
    p.vy = Math.sin(angle) * 150; 
    p.vz = 350; // Pop up high
    p.life = 1.5; p.maxLife = 1.5;
    p.color = '#fff'; p.size = 64 * 0.6; 
    p.type = 'SPRITE'; p.image = assets.icon;
    p.rotation = Math.random() * Math.PI * 2; 
    p.vRotation = (Math.random() - 0.5) * 40; // Fast spin
    system.state.particles.push(p);

    // 2. Base Debris (Heavy, Darker)
    for (let i = 0; i < 5; i++) {
        const p = system.state.getParticle();
        const angle = (i / 5) * Math.PI * 2;
        p.x = x; p.y = y; p.z = 10;
        // Explode outward
        const speed = 150 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 150 + Math.random() * 150; 
        p.life = 2.0; p.maxLife = 2.0;
        p.color = baseColor; 
        p.size = 8 + Math.random() * 8; // Chunky
        p.type = 'DEBRIS'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*15;
        system.state.particles.push(p);
    }

    // 3. Armor Shards (Light, Neon/Colored)
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        const angle = Math.random() * Math.PI * 2;
        p.x = x; p.y = y; p.z = 40; // Higher center
        // Fly further
        const speed = 200 + Math.random() * 200;
        p.vx = Math.cos(angle) * speed; 
        p.vy = Math.sin(angle) * speed; 
        p.vz = 250 + Math.random() * 250; 
        p.life = 1.5; p.maxLife = 1.5;
        p.color = Math.random() > 0.5 ? armorColor : theme.secondary; 
        p.size = 5 + Math.random() * 5; // Smaller, sharper
        p.type = 'SHARD'; 
        p.rotation = angle; 
        p.vRotation = (Math.random()-0.5)*25;
        system.state.particles.push(p);
    }

    // 4. Soul Release (Vertical Beam/Glow)
    const soul = system.state.getParticle();
    soul.x = x; soul.y = y; soul.z = 10;
    soul.vx = 0; soul.vy = 0; soul.vz = 20; // Slowly rise
    soul.life = 0.8; soul.maxLife = 0.8;
    soul.color = glowColor;
    soul.size = 120;
    soul.type = 'PILLAR'; // Use miniature pillar effect
    system.state.particles.push(soul);

    // 5. Ground Scorch
    addDecal(system, x, y, '#000'); 
    spawnShockwave(system, x, y, glowColor, 0.4);
    spawnExplosion(system, x, y, 40, 15, baseColor, 0.8, 0.8, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE' | 'SHARD' | 'DEBRIS') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        // Higher velocity spread for kinetic feel
        const spd = Math.random() * 200 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 200 + 100) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        // Size varies more
        p.size = type === 'SPARK' ? Math.random() * 4 + 3 : Math.random() * 20 + 20;
        if (type === 'SHARD' || type === 'DEBRIS') p.size = 5 + Math.random() * 5;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING' | 'BLAST' | 'SHOCKWAVE', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 30; // Default size
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                // Check for High-Tier Ultimates first
                if (event.skill) {
                    // Tactical Nuke (Red Ranger Ult 2)
                    if (event.skill.id === 'rr_u2') {
                        VFXSpawners.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, event.color || '#ef4444');
                        camera.addTrauma(0.8); // MASSIVE SHAKE
                        return;
                    }
                    // Meteor (Red Mage Ult 1)
                    if (event.skill.id === 'mr_u1') {
                        VFXSpawners.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, event.color || '#ea580c');
                        camera.addTrauma(0.6);
                        return;
                    }
                    // Black Hole (Blue Mage Ult 1)
                    if (event.skill.id === 'mb_u1') {
                        VFXSpawners.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#000');
                        camera.addTrauma(0.4);
                        return;
                    }
                }

                // Default AOE Blast
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                // Only handle special visuals if not handled by IMPACT_AOE
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05); // Minimal impact
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                // High Impact Cast Break
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     // Very slight nudge on Ult finish
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // Check for specific single target ults
            if (skill && skill.id === 'wr_u1') { // Ragnarok
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS'); // Blood explosion
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } else {
                // Generic Single Target Ult
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }

        } else {
            // --- NORMAL SKILLS (Specific Visuals) ---

            // 1. SMASH: Heavy Ground Impact
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                // Debris flies up
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            // 2. SLASH: Directional Energy
            else if (visualType === 'SLASH') {
                // Direction calculated relative to source
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            // 3. FIREBALL / BOMB: Volumetric Explosion
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            // 4. BOLT / ARROW / BEAM: High Precision
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks)
            // No gravity feel. Just pure energy moving fast.
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            // Stretch based on speed, but clamp it
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); // Align with motion

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); // Stretch length, squash width

            ctx.globalCompositeOperation = 'lighter'; // Additive blending for glow
            ctx.globalAlpha = Math.pow(1 - progress, 2); // Fade out non-linearly

            // Streamlined Shape
            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); // Bright head
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE / FIRE CLOUD
            const scale = 0.5 + progress * 2.0; // Expands more
            const alpha = (1 - progress) * 0.6; // Slightly more opaque start

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress * 0.5); // Slowly rotates
            ctx.globalAlpha = alpha;

            // Enhanced Shading for Explosions
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(1, 'rgba(0,0,0,0)'); // Soft edge

            ctx.fillStyle = grad;

            // Draw cluster
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            // Add irregularities
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE (Sonic Boom)
            ctx.scale(1, 0.55); // Isometric
            const r = progress * p.size * 2; // Expands outward

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;

            // Main Ring
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            // Echo Ring (Inner)
            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            // Spiky Circle
            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                // Add noise to radius
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 MATERIAL 2.0: ENHANCED DEBRIS
            // Uses gradients to simulate lighting/metallic surface

            ctx.rotate(p.rotation);

            // Base Gradient (Simulate light from top-left)
            const grad = ctx.createLinearGradient(-p.size, -p.size, p.size, p.size);
            grad.addColorStop(0, '#ffffff'); // Specular highlight
            grad.addColorStop(0.3, p.color);
            grad.addColorStop(1, '#000000'); // Shadow side

            ctx.fillStyle = grad;

            // Rim Light (Edge definition)
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                // Irregular jagged shard
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size * 0.8, -p.size * 0.2); 
                ctx.lineTo(0, p.size); 
                ctx.lineTo(-p.size * 0.5, p.size * 0.5);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            // ✨ STATIC GLOW ORB (Pre-rendered)
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); // Pulse: Fade In -> Fade Out
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                // Sprite fades out and shrinks slightly
                const alpha = Math.max(0, 1 - Math.pow(progress, 3)); 
                ctx.globalAlpha = alpha;

                // Spin faster as it dies (angular momentum conservation fake)
                ctx.rotate(p.rotation + progress * 5);

                const perspective = 1.0 + (p.z * 0.002);
                const scale = (p.size / 64) * perspective * (1 - progress * 0.5); 
                ctx.scale(scale, scale);

                // Add a "Ghost" trail effect by drawing lower opacity copies
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM (Optimized)
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();
        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 3.0
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        let alpha = lifeRatio > 0.8 ? (1 - lifeRatio) * 5 : (lifeRatio < 0.2 ? lifeRatio * 5 : 1.0);
        // Decrease max height slightly for "Soul" usage
        const maxHeight = p.size * 12; // Dynamic height based on size
        const width = p.size; 

        ctx.save();
        ctx.globalCompositeOperation = 'screen'; 

        // Base
        ctx.save();
        ctx.scale(1, 0.58);
        ctx.rotate(Date.now() * 0.002);
        ctx.fillStyle = p.color;
        ctx.globalAlpha = alpha * 0.4;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.fill();
        ctx.strokeStyle = p.color; ctx.lineWidth = 3; ctx.globalAlpha = alpha * 0.8; ctx.stroke();
        ctx.restore();

        // Beam
        const coreWidth = width * 0.5;
        const beamGrad = ctx.createLinearGradient(-coreWidth, 0, coreWidth, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, '#ffffff'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.9;
        ctx.fillRect(-coreWidth, -maxHeight, coreWidth * 2, maxHeight);

        // Data Streams
        const lines = 8;
        for(let i=0; i<lines; i++) {
            const offsetX = (Math.random() - 0.5) * width * 1.6;
            const speed = 2500 + Math.random() * 1500;
            const yPos = -((Date.now() * speed / 2000 + i * 137) % maxHeight);
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = alpha * (0.6 + Math.random()*0.4);
            ctx.fillRect(offsetX - 2, yPos, 4, 100); 
        }
        ctx.restore();
    },

    // 🩸 BLOOD RITUAL
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // Void Hole
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); 
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Cracks
         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();
         ctx.restore();

         // Rising Heat
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        const r = progress * p.size; // Expands to max size
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";
