import { GameEvent, Team } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import * as VFXSpawners from "../vfx/spawners";

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
        const visualGroundY = event.pos.y - terrainHeight;

        switch (event.type) {
            case 'VISUAL_SLASH':
                this.handleSlash(event, engine, grid, vfx, visualGroundY);
                break;

            case 'DAMAGE': 
                // Only spawn impact if it wasn't a projectile hit (which handles its own visuals)
                // or if it's a direct instant damage event.
                if (!event.skill?.projectileSpeed) {
                    this.handleDamageImpact(event, engine, vfx, visualGroundY, camera);
                }
                break;

            case 'VISUAL_BEAM':
                this.handleBeam(event, engine, grid, vfx, visualGroundY);
                break;

            case 'IMPACT_AOE':
                // 1. UNIVERSAL GRID REACTION (The "Floor Tile Explosion")
                if (event.skill) {
                    const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                    const radius = event.skill.aoeRadius || 1;
                    const affectedHexes = HexUtils.range(centerHex, radius);

                    // 2. SPECIALIZED ULTIMATE VFX (Cinematic Layer)
                    const id = event.skill.id;
                    const color = event.color || '#fff';

                    // --- BLUE FACTION ULTS ---

                    // 🛰️ Divine Intervention (Support Blue Ult 1)
                    // REWORKED: Instead of one big beam, rain down light on EVERY tile in range with ripple
                    if (id === 'sb_u1') {
                        affectedHexes.forEach(h => {
                            if (engine.map.isValid(h.q, h.r)) {
                                const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                                const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                                const tileVisualY = tilePos.y - hHeight;

                                // Ripple Logic: Delay based on distance from center
                                const dist = HexUtils.dist(centerHex, h);
                                const delay = dist * 0.08; // 80ms wave speed per tile

                                // Spawn independent, grid-sized pillar
                                VFXSpawners.spawnDivinePillar(
                                    vfx, 
                                    tilePos.x, 
                                    tileVisualY, 
                                    color, 
                                    0.8, // Shorter life
                                    delay
                                );
                            }
                        });
                        camera.addTrauma(0.5);
                        return; // Skip generic explosion
                    }

                    // ✝️ Grand Cross (Tank Blue Ult 1)
                    if (id === 'tb_u1') {
                        VFXSpawners.spawnGrandCross(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }

                    // --- RED FACTION ULTS ---
                    // ☢️ Tactical Nuke (Ranger Red Ult 2)
                    if (id === 'rr_u2') {
                        VFXSpawners.spawnTacticalNuke(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.8); 
                        return;
                    }
                    // ☄️ Meteor (Mage Red Ult 1)
                    if (id === 'mr_u1') {
                        VFXSpawners.spawnMeteorImpact(vfx, event.pos.x, visualGroundY, color);
                        camera.addTrauma(0.6);
                        return;
                    }
                    // 🕳️ Black Hole (Mage Blue Ult 1 - Event Horizon)
                    if (id === 'mb_u1') {
                        VFXSpawners.spawnBlackHoleCollapse(vfx, event.pos.x, visualGroundY, '#000');
                        camera.addTrauma(0.4);
                        return;
                    }

                    // Generic Grid Reaction for non-special AOEs
                    affectedHexes.forEach(h => {
                        if (engine.map.isValid(h.q, h.r)) {
                            const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                            const hHeight = grid.getTerrainHeight(h.q, h.r, engine);
                            const tileVisualY = tilePos.y - hHeight;
                            const dist = HexUtils.dist(centerHex, h);
                            const delay = dist * 0.06;

                            VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, event.color || '#fff', Team.BLUE, delay);
                        }
                    });
                }

                // 3. GENERIC AOE BLAST (Fallback)
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 0, 20, event.color || '#fff', 2.0, 0.6, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualGroundY, 0, event.color || '#fff', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualGroundY, event.color || '#fff', 0.6);
                camera.addTrauma(0.25); 
                break;

            case 'PROJECTILE_HIT': 
                if (event.skill?.type !== 'AOE') {
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                } else {
                    // For AOE hits, we skip individual pillars/rituals to prevent visual clutter
                    // But we still show impact debris/flash
                    const hitColor = event.skill?.color || '#fff';
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 20, 8, hitColor, 1.0, 0.3, 'SPARK');
                }
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                camera.addTrauma(0.05);
                break;

            case 'SPAWN':
                VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                break;

            case 'CAST_BREAK':
                VFXSpawners.spawnCastBreak(vfx, event.pos.x, visualGroundY, event.value || 1, event.color || '#fff');
                camera.addTrauma(0.3); 
                break;

            case 'CAST_FINISH':
                if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.05); 
                     }
                 }
                 break;
        }
    }

    private handleSlash(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId && event.targetId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            const target = engine.agents.find(a => a.id === event.targetId);
            if (source && target) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
            }
        }
    }

    private handleBeam(event: GameEvent, engine: GameEngine, grid: GridSystem, vfx: VFXSystem, visualGroundY: number) {
        if (event.sourceId) {
            const source = engine.agents.find(a => a.id === event.sourceId);
            if (source) {
                const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);

                // Special Visual for Death Finger (mr_u2)
                if (event.skill?.id === 'mr_u2') {
                    VFXSpawners.spawnDeathRay(vfx, source.px, source.py - sH - 45, event.pos.x, visualGroundY - 30, event.color || '#be123c');
                    return;
                }

                VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
            }
        }
    }

    private handleDamageImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, visualGroundY: number, camera: CameraSystem) {
        const dmg = Math.abs(event.value || 0);

        if (event.sourceId && event.targetId) {
            const s = engine.agents.find(a => a.id === event.sourceId);
            const t = engine.agents.find(a => a.id === event.targetId);
            if (s && t) {
                const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                const dx = t.px - s.px; const dy = t.py - s.py;
                const len = Math.sqrt(dx*dx + dy*dy);
                if (len > 0) {
                    const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                }
            }
        } else {
            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
        }

        if (dmg > 50) camera.addTrauma(0.05); // Minimized
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;
        const visualType = skill?.visual || 'BOLT';

        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.15); 

            // Special handling for Death Finger (mr_u2) target hit - KILL THE PILLAR
            if (skill && skill.id === 'mr_u2') {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#000', 3.0, 0.5, 'SPARK');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, '#be123c', 'BLAST', 0.5);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, visualY, '#000', 0.5);
                return; // Early return prevents BloodRitual
            }

            // 1. FACTION RITUAL (The Ground Effect)
            if (faction === Team.BLUE) {
                // For Blue faction normal ult hits (single target), use a smaller fast pillar
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 0.6, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 0.8);
            } else {
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            if (skill && skill.id === 'wr_u1') { // Ragnarok
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 50, '#991b1b', 2.0, 1.0, 'DEBRIS');
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 0, '#ef4444', 'BLAST', 0.8);
                camera.addTrauma(0.5);
            } else {
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }

        } else {
            if (visualType === 'SMASH') {
                VFXSpawners.addImpact(vfx, event.pos.x, centerVisualY, 0, color, 'SHOCKWAVE', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, centerVisualY, 0, 8, color, 0.5, 0.6, 'SHARD'); 
            } 
            else if (visualType === 'SLASH') {
                if (source) {
                    const dx = event.pos.x - source.px;
                    const dy = event.pos.y - source.py;
                    const len = Math.sqrt(dx*dx + dy*dy) || 1;
                    VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualY, 30, dx/len, dy/len, color, 'PHYSICAL');
                } else {
                    VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 8, color, 1.5, 0.4, 'SPARK');
                }
            }
            else if (visualType === 'FIREBALL' || visualType === 'BOMB') {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 20, color, 'BLAST', 0.5);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 5, color, 0.5, 1.0, 'SMOKE');
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 20, 8, '#fff', 1.0, 0.3, 'SPARK');
            }
            else {
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.4);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 2.0, 0.4, 'SPARK');
            }
        }
    }
}

import { Particle } from "../state";
import { isChaosStyle } from "../utils";
import { AssetManager } from "../../../assets";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Context is already translated to Visual Position (Ground Y - Z)
        ctx.translate(p.x, p.y);

        // --- PHYSICAL SHADOW PASS ---
        if (['DEBRIS', 'SHARD', 'SPRITE'].includes(p.type) && p.z > 5) {
            ctx.save();
            ctx.translate(0, p.z); // Move "down" to ground level
            ctx.scale(1, 0.5); // Isometric shadow squash
            const shadowAlpha = Math.max(0, 0.3 - (p.z / 400)); // Lighter shadow
            if (shadowAlpha > 0) {
                ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
                const shadowSize = p.size * 0.8;
                ctx.beginPath(); ctx.arc(0, 0, shadowSize, 0, Math.PI * 2); ctx.fill();
            }
            ctx.restore();
        }

        // --- RENDER LOGIC BY TYPE ---

        if (p.type === 'SPARK') {
            // ✨ KINETIC SPARKS (Light Streaks)
            const speed = Math.sqrt(p.vx*p.vx + p.vy*p.vy + p.vz*p.vz);
            const stretch = Math.min(4.0, 1.0 + speed / 150); 
            const angle = Math.atan2(p.vy, p.vx); 

            ctx.rotate(angle);
            ctx.scale(stretch, 0.6); 

            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = Math.pow(1 - progress, 2); 

            // Streamlined Shape
            const grad = ctx.createLinearGradient(-p.size, 0, p.size, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.2, p.color);
            grad.addColorStop(0.8, '#fff'); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(0, 0, p.size, p.size * 0.5, 0, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'SMOKE') {
            // ☁️ VOLUMETRIC SMOKE
            const scale = 0.5 + progress * 2.0; 
            const alpha = (1 - progress) * 0.6; 

            ctx.scale(scale, scale);
            ctx.rotate(p.rotation + progress * 0.5); 
            ctx.globalAlpha = alpha;

            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, p.size);
            grad.addColorStop(0, p.color);
            grad.addColorStop(1, 'rgba(0,0,0,0)'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.arc(0, 0, p.size, 0, Math.PI*2);
            ctx.arc(p.size*0.5, p.size*0.5, p.size*0.6, 0, Math.PI*2);
            ctx.arc(-p.size*0.4, -p.size*0.3, p.size*0.7, 0, Math.PI*2);
            ctx.fill();

        } else if (p.type === 'RING') {
            // 🌊 ENERGY RIPPLE
            ctx.scale(1, 0.55); 
            const r = progress * p.size * 2; 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 4;
            ctx.globalAlpha = 1 - progress;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

            if (progress > 0.2) {
                ctx.lineWidth = (1 - progress) * 2;
                ctx.globalAlpha = (1 - progress) * 0.5;
                ctx.beginPath(); ctx.arc(0, 0, r * 0.7, 0, Math.PI * 2); ctx.stroke();
            }

        } else if (p.type === 'BLAST') {
            // 💥 SPIKED EXPLOSION
            ctx.scale(1, 0.55); 
            const r = p.size * (progress); 

            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 6; 
            ctx.globalAlpha = (1 - progress);

            ctx.beginPath(); 
            const spikes = 12;
            for(let i=0; i<=spikes; i++) {
                const angle = (i/spikes) * Math.PI*2;
                const rad = r * (1.0 + (i%2===0 ? 0.2 : 0)); 
                const px = Math.cos(angle) * rad;
                const py = Math.sin(angle) * rad;
                if(i===0) ctx.moveTo(px,py); else ctx.lineTo(px,py);
            }
            ctx.closePath();
            ctx.stroke();

        } else if (p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'CHIP') {
            // 💎 MATERIAL
            ctx.rotate(p.rotation);

            const grad = ctx.createLinearGradient(-p.size, -p.size, p.size, p.size);
            grad.addColorStop(0, '#ffffff'); 
            grad.addColorStop(0.3, p.color);
            grad.addColorStop(1, '#000000'); 

            ctx.fillStyle = grad;
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;

            if (p.type === 'CHIP') {
                ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);
            } else {
                ctx.beginPath();
                ctx.moveTo(-p.size, -p.size/2); 
                ctx.lineTo(p.size * 0.8, -p.size * 0.2); 
                ctx.lineTo(0, p.size); 
                ctx.lineTo(-p.size * 0.5, p.size * 0.5);
                ctx.closePath();
                ctx.fill();
                ctx.stroke();
            }

        } else if (p.type === 'GLOW') {
            const img = AssetManager.getGlowSprite(p.color);
            const fade = Math.sin(progress * Math.PI); 
            const scale = (p.size / 64) * (0.8 + fade * 0.4); 

            ctx.globalAlpha = fade * 0.9;
            ctx.globalCompositeOperation = 'screen'; 
            ctx.scale(scale, scale);
            ctx.drawImage(img, -32, -32);

        } else if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.max(0, 1 - Math.pow(progress, 3)); 
                ctx.globalAlpha = alpha;
                ctx.rotate(p.rotation + progress * 5);
                const perspective = 1.0 + (p.z * 0.002);
                const scale = (p.size / 64) * perspective * (1 - progress * 0.5); 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                this.drawHelixBeam(ctx, p, progress);
            }
        } else if (p.type === 'DEATH_RAY') {
            this.drawDeathRay(ctx, p, progress);
        } else if (p.type === 'PILLAR') {
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        } else if (p.type === 'GRID_FIELD') {
            this.drawGridField(ctx, p, progress, isChaos);
        }

        ctx.restore();
    },

    // ⚡ HELIX BEAM
    drawHelixBeam(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 
        ctx.globalCompositeOperation = 'lighter';

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        const beamWidth = 6 * (1 - Math.pow(progress, 3)); 
        if (beamWidth < 0.2) return;

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        // Core
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = Math.max(2, beamWidth * 0.5);
        ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Glow
        ctx.strokeStyle = p.color;
        ctx.lineWidth = beamWidth * 2.5; 
        ctx.globalAlpha = 0.5 * (1 - progress);
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(dist, 0); ctx.stroke();

        // Helix
        const freq = 0.12; 
        const amp = 8 * (1 - progress); 
        const phase = Date.now() * 0.025; 

        ctx.lineWidth = 2; 
        ctx.globalAlpha = 0.9 * (1 - progress);
        ctx.strokeStyle = p.color; 

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        ctx.beginPath();
        for(let i=0; i<=dist; i+=5) {
            const yOffset = Math.sin(i * freq - phase + Math.PI) * amp;
            if(i===0) ctx.moveTo(i, yOffset); else ctx.lineTo(i, yOffset);
        }
        ctx.stroke();

        // Flares
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 1 - progress;
        ctx.beginPath(); ctx.arc(0, 0, beamWidth * 1.5, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(dist, 0, beamWidth * 2.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    // ☠️ DEATH RAY (High Velocity Particle Beam)
    drawDeathRay(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.translate(-p.x, -p.y); 

        const sx = p.x; const sy = p.y;
        const tx = p.targetX!; const ty = p.targetY!;
        const dx = tx - sx;
        const dy = ty - sy;
        const dist = Math.sqrt(dx*dx + dy*dy);
        const angle = Math.atan2(dy, dx);

        ctx.save();
        ctx.translate(sx, sy);
        ctx.rotate(angle);

        const alpha = Math.pow(1 - progress, 2);

        // 1. Dark Void Core (Source-Over to block light)
        ctx.globalCompositeOperation = 'source-over'; 
        ctx.strokeStyle = '#000';
        ctx.lineWidth = 4 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 2. Intense Crimson Glow (Lighter)
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color; 
        ctx.lineWidth = 12 * alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 20;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();
        ctx.shadowBlur = 0;

        // 3. White Hot Needle Center
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath(); ctx.moveTo(0,0); ctx.lineTo(dist, 0); ctx.stroke();

        // 4. Chaotic Crackles
        ctx.strokeStyle = '#fca5a5'; 
        ctx.lineWidth = 2 * alpha;
        ctx.beginPath();
        let cx = 0;
        ctx.moveTo(0, 0);
        const segmentLen = 40;
        const steps = Math.ceil(dist / segmentLen);
        for(let i=0; i<steps; i++) {
            cx += segmentLen;
            const cy = (Math.random() - 0.5) * 20 * alpha;
            ctx.lineTo(cx, cy);
        }
        ctx.lineTo(dist, 0);
        ctx.stroke();

        ctx.restore();
    },

    // 🌫️ VOLUMETRIC GRID FOG
    drawGridField(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        const size = 36; 
        const drawHex = () => {
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
                const x = size * Math.cos(angle);
                const y = size * Math.sin(angle) * 0.58; 
                if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
            }
            ctx.closePath();
        };

        const fade = Math.sin(progress * Math.PI); 
        ctx.save();

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over';
            ctx.save();
            const jitter = (Math.random() - 0.5) * 2;
            ctx.translate(jitter, jitter);
            drawHex();
            ctx.clip();
            ctx.fillStyle = `rgba(20, 5, 5, ${fade * 0.8})`;
            ctx.fill();
            ctx.strokeStyle = p.color; 
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade;
            ctx.beginPath();
            ctx.moveTo(-20, -10); ctx.lineTo(-10, 5); ctx.lineTo(5, -5); ctx.lineTo(20, 10);
            ctx.moveTo(0, 0); ctx.lineTo(-5, 15);
            ctx.stroke();
            ctx.restore();
        } else {
            ctx.globalCompositeOperation = 'screen';
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 4;
            ctx.globalAlpha = fade * 0.4;
            drawHex();
            ctx.stroke();
            ctx.lineWidth = 2;
            ctx.globalAlpha = fade * 0.8;
            drawHex();
            ctx.stroke();
            ctx.fillStyle = p.color;
            ctx.globalAlpha = fade * 0.2;
            ctx.fill();
        }
        ctx.restore();
    },

    // 🏛️ DIVINE PILLAR 4.0: THIN SHAFT (Clean Edition)
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;

        let alpha = 0;
        if (lifeRatio > 0.8) alpha = (1 - lifeRatio) * 5; 
        else if (lifeRatio < 0.3) alpha = lifeRatio * 3.3; 
        else alpha = 1.0;

        const height = 800; 
        const width = p.size; // Strictly respects spawn size (18)

        // --- 1. THE BEAM CORE ---
        ctx.save();
        // Use source-over to prevent additive blowout when multiple beams overlap
        ctx.globalCompositeOperation = 'source-over'; 

        const beamGrad = ctx.createLinearGradient(-width, 0, width, 0);
        beamGrad.addColorStop(0, 'rgba(255,255,255,0)');
        beamGrad.addColorStop(0.2, p.color);
        beamGrad.addColorStop(0.5, 'rgba(255,255,255,0.6)'); 
        beamGrad.addColorStop(0.8, p.color);
        beamGrad.addColorStop(1, 'rgba(255,255,255,0)');

        // Vertical fade
        const vGrad = ctx.createLinearGradient(0, 0, 0, -height);
        vGrad.addColorStop(0, 'rgba(255,255,255,1)');
        vGrad.addColorStop(0.8, 'rgba(255,255,255,0.5)');
        vGrad.addColorStop(1, 'rgba(255,255,255,0)');

        ctx.fillStyle = beamGrad;
        ctx.globalAlpha = alpha * 0.7; 
        ctx.fillRect(-width, -height, width * 2, height);

        // --- 2. GROUND RIPPLE (Impact Ring) ---
        ctx.save();
        ctx.scale(1, 0.58); 

        // Ground glow is okay to be Screen
        ctx.globalCompositeOperation = 'screen';
        const ringSize = width * 1.5 * (0.5 + (1-lifeRatio)); 

        ctx.strokeStyle = p.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha * 0.9;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.stroke();

        // Center spot
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath(); ctx.arc(0, 0, width * 0.5, 0, Math.PI*2); ctx.fill();

        ctx.restore();
        ctx.restore();
    },

    // 🩸 BLOOD RITUAL
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // Void Hole
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); 
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // Cracks
         ctx.strokeStyle = p.color; 
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();
         ctx.restore();

         // Rising Heat
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); ctx.lineTo(-r/4, -300); ctx.lineTo(r/4, -300); ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        const r = progress * p.size; // Expands to max size
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};
